import{_ as l,l as o,o as e,c as n,v as t,p as s,x as r,d as E,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const R=JSON.parse('{"title":"语言混杂","description":"","frontmatter":{"title":"语言混杂","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/language-mixing-reasoning.md","filePath":"llm/language-mixing-reasoning.md","lastUpdated":1789023840000}'),A={name:"llm/language-mixing-reasoning.md"};function h(m,a,c,_,B,u){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="语言混杂" tabindex="-1">语言混杂 <a class="header-anchor" href="#语言混杂" aria-label="Permalink to &quot;语言混杂&quot;">​</a></h1><div class="epigraph"><p>R1-Zero 在中英之间来回切：对校验器无成本，对用户不可读；冷启动 SFT 要把语言当格式约束补回去。</p><footer>—— DeepSeek-AI R1 对 R1-Zero 可读性与语言混合问题的修复路径</footer></div><p><a href="/llm/aha-moment">上一课</a>的探索相变会一并强化「碰巧常赢」的表面形式。缺口是：<strong>校验器只看最终答案，链的语言不进 \\(R\\)，于是中英夹杂、语码转换成为无成本的工作记忆。</strong> R1 用冷启动可读长链 + 多阶段训练修复。本课写混杂的原因与约束，接到忠实性：可读 ≠ 忠实。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>基座多语言。数学符号与英文术语在预训练里与中文叙述混排。RL 只奖 boxed 数字，混杂不降 \\(R\\)，有时还升（某些英文推理片段更常对）。产品要求单一语言或用户语言。这是多目标里漏掉的轴：语言一致性。</p><p>R1-Zero 跳过 SFT，没有「用用户语言写思维」的示范，混杂更重。R1 冷启动先示范可读链，再 RL，混杂下降。代价是探索可能变窄。数学符号、变量名、代码标识符不应计入「外语」；语码转换统计要排除公式环境，否则会把合法证明当混杂。</p><h3 id="不要用语言识别当主奖励" tabindex="-1">不要用语言识别当主奖励 <a class="header-anchor" href="#不要用语言识别当主奖励" aria-label="Permalink to &quot;不要用语言识别当主奖励&quot;">​</a></h3><p>重罚混杂会让模型为了语言牺牲搜索，难题准确率掉。应：格式轻约束 + 示范，金标仍是对错。与过长惩罚一样，权重按产品扫。</p><p><span class="marginnote">思维对用户隐藏时，混杂仍影响监视器可读性（monitorability）。内部链也需要语言政策。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>测量：语码转换次数、主语言占比、用户语言一致率。训练：冷启动 SFT 锁语言；RL 加轻量语言一致项或约束解码（不允许切语言——可能伤数学符号，要白名单）。评测：准确率与可读性分表。蒸馏学生：教师链若混杂，学生会学混杂，过滤或改写教师链。</p>',11)),(e(),s(d,null,{default:r(()=>[p(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20R0%5B%22R1-Zero%EF%BC%9A%E5%8F%AA%E5%A5%96%E5%AF%B9%E9%94%99%22%5D%20--%3E%20MIX%5B%22%E9%93%BE%E4%B8%8A%E8%AF%AD%E8%A8%80%E6%B7%B7%E6%9D%82%22%5D%0A%20%20CS%5B%22%E5%86%B7%E5%90%AF%E5%8A%A8%E5%8F%AF%E8%AF%BB%E9%95%BF%E9%93%BE%22%5D%20--%3E%20R1%5B%22%E5%86%8D%20RL%22%5D%0A%20%20R1%20--%3E%20READ%5B%22%E5%8F%AF%E8%AF%BB%E6%80%A7%E5%9B%9E%E5%8D%87%22%5D%0A%20%20LANG%5B%22%E8%BF%87%E5%BC%BA%E8%AF%AD%E8%A8%80%E6%83%A9%E7%BD%9A%22%5D%20--%3E%20DROP%5B%22%E9%9A%BE%E9%A2%98%E5%87%86%E7%A1%AE%E7%8E%87%E4%B8%8B%E9%99%8D%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与混合思考：短模式更易保持用户语言；思维模式是重灾区。分模式约束。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>无成本维度会被 RL 当工作记忆用。语言、标记符号、重复填充都是候选。约束哪个，取决于产品与监视。完全不约束，监视和摘要器失败。约束过死，回到短 SFT 分布，aha / 回溯减少。R1 的多阶段是折中，不是定理。</p><p><span class="marginnote">「用户用中文问、答案中文、思维英文」有时是可接受的内部政策，但必须声明，不能当意外。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>纯英文题库上混杂不明显，不代表多语言部署安全。本课对中文产品尤其硬。下一课忠实性：即使用户语言干净，链仍可能不对应内部计算。</p><p>语码统计要排除公式与代码。语言轻约束加冷启动，重罚会打压搜索；内部链语言仍影响监视可读性。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>语言混杂因校验器不给语言定价而出现；探索相变会放大它。</li><li>冷启动可读示范 + 轻约束，优于重罚语言。</li><li>内部链语言政策影响监视，不只影响 UI。</li><li>蒸馏会复制教师混杂，需过滤。</li><li>出处：DeepSeek-AI R1 对 Zero 混语言与冷启动修复的报告。</li></ul>',9))])}const D=l(A,[["render",h]]);export{R as __pageData,D as default};
